package binarysearch

import "testing"

func TestFoundMiddle(t *testing.T) {
	if got := BinarySearch([]int{1, 3, 5, 7, 9}, 5); got != 2 {
		t.Fatalf("got %d, want 2", got)
	}
}

func TestFoundFirst(t *testing.T) {
	if got := BinarySearch([]int{1, 3, 5, 7, 9}, 1); got != 0 {
		t.Fatalf("got %d, want 0", got)
	}
}

func TestFoundLast(t *testing.T) {
	if got := BinarySearch([]int{1, 3, 5, 7, 9}, 9); got != 4 {
		t.Fatalf("got %d, want 4", got)
	}
}

func TestMissing(t *testing.T) {
	if got := BinarySearch([]int{1, 3, 5, 7, 9}, 4); got != -1 {
		t.Fatalf("got %d, want -1", got)
	}
}

func TestEmpty(t *testing.T) {
	if got := BinarySearch([]int{}, 1); got != -1 {
		t.Fatalf("got %d, want -1", got)
	}
}

func TestSingleHit(t *testing.T) {
	if got := BinarySearch([]int{42}, 42); got != 0 {
		t.Fatalf("got %d, want 0", got)
	}
}

func TestSingleMiss(t *testing.T) {
	if got := BinarySearch([]int{42}, 7); got != -1 {
		t.Fatalf("got %d, want -1", got)
	}
}
